class ActivationBlock {HHOOK hook_=nullptr;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int code,WPARAM wp,LPARAM lp)->LRESULT{return code==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,code,wp,lp);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate menu fixture");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
std::vector<UINT> Leaves(CMenu& menu){std::vector<UINT> out;for(int i=0;i<menu.GetMenuItemCount();++i){auto* sub=menu.GetSubMenu(i);if(sub){auto child=Leaves(*sub);out.insert(out.end(),child.begin(),child.end());}else{UINT id=menu.GetMenuItemID(i);if(id&&id!=static_cast<UINT>(-1))out.push_back(id);}}return out;}
